import{_ as n,o as r,c as s,a2 as o}from"./chunks/framework.Zh78JZbW.js";const g=JSON.parse('{"title":"Premier lancement","description":"","frontmatter":{},"headers":[],"relativePath":"guide/premier-lancement.md","filePath":"guide/premier-lancement.md"}'),i={name:"guide/premier-lancement.md"};function a(t,e,l,c,u,d){return r(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="premier-lancement" tabindex="-1">Premier lancement <a class="header-anchor" href="#premier-lancement" aria-label="Permalink to &quot;Premier lancement&quot;">​</a></h1><p>Au premier lancement, Kodus vous demande de choisir un pseudo, puis de créer votre première instance (une configuration de Minecraft, voir le <a href="./lexique">glossaire</a>).</p><ol><li><strong>Choisissez votre pseudo</strong> : de 3 à 16 caractères (lettres, chiffres ou <code>_</code>). C&#39;est le nom affiché en jeu. Vous pourrez le modifier dans les <strong>Paramètres</strong> (icône d&#39;engrenage en haut à droite de l&#39;accueil).</li><li><strong>Créez une instance</strong> dans la fenêtre « Nouvelle instance » : <ul><li><strong>Nom</strong> : au choix, par exemple « Survie ».</li><li><strong>Version</strong> : la version de Minecraft. Pour rejoindre un serveur, choisissez la même version que celui-ci ; sinon, la version la plus récente proposée convient.</li><li><strong>Loader</strong> : conservez <strong>Fabric</strong> (sélectionné par défaut) pour utiliser des mods, ou choisissez <strong>Vanilla</strong> pour le jeu de base. Les loaders grisés ne sont pas disponibles pour la version choisie.</li><li><strong>RAM allouée</strong> : conservez la valeur par défaut.</li></ul></li><li>Cliquez sur <strong>Créer</strong>, puis sur le bouton <strong>Jouer</strong> de l&#39;accueil.</li></ol><div class="info custom-block"><p class="custom-block-title">Durée du premier lancement</p><p>Le premier lancement prend quelques minutes : Kodus télécharge Java et le jeu (plusieurs centaines de Mo). La barre de progression située sous le bouton indique l&#39;avancement. Les lancements suivants sont quasi immédiats.</p></div><h2 id="l-ecran-d-accueil" tabindex="-1">L&#39;écran d&#39;accueil <a class="header-anchor" href="#l-ecran-d-accueil" aria-label="Permalink to &quot;L&#39;écran d&#39;accueil&quot;">​</a></h2><ul><li><strong>Jouer</strong> et le menu situé en dessous : lancent l&#39;instance sélectionnée.</li><li><strong>Temps de jeu</strong> et <strong>Monde le plus joué</strong> : statistiques de l&#39;instance sélectionnée.</li><li><strong>Icône d&#39;image</strong> (en haut à droite) : l&#39;ensemble de vos captures d&#39;écran (touche F2 en jeu), filtrables par instance.</li><li><strong>Icône d&#39;engrenage</strong> : les Paramètres (pseudo, skin, animation de fond, mises à jour).</li><li><strong>Colonne de gauche</strong> : la liste de vos instances. Un clic ouvre la page de l&#39;instance (mods, logs, réglages) ; le logo Kodus en haut ramène à l&#39;accueil.</li></ul>',6)])])}const p=n(i,[["render",a]]);export{g as __pageData,p as default};
